'use strict';
const $=id=>document.getElementById(id), NS='http://www.w3.org/2000/svg';
let current=null,result=null,selected=null,drawing=[],view=null,drag=null,dirty=false;
let assessmentGeometry=null,assessmentFootprint=null;
let savedViews=false;
const colors={roof:'#52677b',pavement:'#b29872',pervious:'#88b195',unknown:'#d99d42',canopy:'#38745b',vegetation_candidate:'#87c5af',canopy_candidate:'#4a926c',surface_candidate:'#c8a977',footprint:'#ac7099',barrier:'#da615c',inlet:'#438bd0',connection:'#627ad0',benefit:'#a47d23'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n==null?'Unknown':Number(n).toLocaleString(undefined,{maximumFractionDigits:1});
function status(message,error=false){$('status').textContent=message;$('status').className=error?'error':'';}
async function api(path,payload){const r=await fetch(path,payload?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}:{});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d;}
async function action(fn){for(const b of document.querySelectorAll('button'))b.disabled=true;try{await fn();}catch(e){status(e.message,true);}finally{for(const b of document.querySelectorAll('button'))b.disabled=false;}}
function requireCase(){if(!current)throw Error('Open a case first');}
function needReason(){const reason=$('reason').value.trim();if(!reason)throw Error('Enter the evidence and reason for the correction first');return reason;}
function edits(){const base=[...(current?.features.features||[]),...(current?.benefits||[]).filter(b=>b.geometry).map(b=>({type:'Feature',id:b.id,geometry:b.geometry,properties:{layer:'benefit',benefit:b}}))];const map=new Map(base.map(f=>[String(f.id),structuredClone(f)]));for(const e of current?.corrections||[]){if(e.action==='delete'||e.action==='replace')map.delete(String(e.target));if(e.feature)map.set(String(e.feature.id),structuredClone(e.feature));}return [...map.values()];}
function change(edit){current.corrections.push({id:crypto.randomUUID(),at:new Date().toISOString(),reason:needReason(),...edit});dirty=true;result=null;renderMap();showDetails();status('Correction recorded. Rerun to update calculations, then save.');}
function coordinates(geometry){if(geometry.type==='GeometryCollection')return geometry.geometries.flatMap(coordinates);let out=[];function walk(c){if(typeof c[0]==='number')out.push(c);else c.forEach(walk);}walk(geometry.coordinates);return out;}
function fit(){if(!current)return;const coords=coordinates(current.parcel);let xs=coords.map(p=>p[0]),ys=coords.map(p=>-p[1]);let minx=Math.min(...xs),miny=Math.min(...ys),w=Math.max(...xs)-minx,h=Math.max(...ys)-miny;let pad=Math.max(w,h)*.1;view=[minx-pad,miny-pad,w+pad*2,h+pad*2];renderMap();}
function element(tag,attrs={}){const el=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);return el;}
function geometryElement(g,attrs={}){if(g.type==='GeometryCollection'){const group=element('g',attrs);g.geometries.forEach(x=>group.append(geometryElement(x)));return group;}if(g.type==='Point')return element('circle',{cx:g.coordinates[0],cy:-g.coordinates[1],r:view[2]/180,...attrs});if(g.type==='MultiPolygon'||g.type==='MultiLineString'){const group=element('g',attrs);g.coordinates.forEach(c=>group.append(geometryElement({type:g.type==='MultiPolygon'?'Polygon':'LineString',coordinates:c})));return group;}const rings=g.type==='Polygon'?g.coordinates:[g.coordinates];const d=rings.map(r=>'M '+r.map(p=>`${p[0]},${-p[1]}`).join(' L ')+(g.type==='Polygon'?' Z':'')).join(' ');return element('path',{d,'fill-rule':'evenodd',...attrs});}
function renderMap(){const svg=$('map');svg.replaceChildren();if(!current||!view)return;svg.setAttribute('viewBox',view.join(' '));
 if(current.imagery&&$('show-imagery').checked){const im=current.imagery,b=im.bounds;svg.append(element('image',{href:'/api/blob/'+im.sha256,x:b[0],y:-b[3],width:b[2]-b[0],height:b[3]-b[1],preserveAspectRatio:'none',opacity:.85}));}
 if(result&&$('show-modeled').checked){for(const c of result.modeled_integration?.runs?.[0]?.catchments||[]){svg.append(geometryElement(c.geometry,{fill:'none',stroke:'#bb711d','stroke-width':view[2]/550,'stroke-dasharray':`${view[2]/180} ${view[2]/250}`,'pointer-events':'none'}));}}
 if(result&&$('show-research').checked){for(const c of result.research_drainage?.primary?.catchments||[]){svg.append(geometryElement(c.geometry,{fill:'#9b51b5','fill-opacity':.12,stroke:'#863b9f','stroke-width':view[2]/650,'pointer-events':'none'}));}}
 if(result&&$('show-drainage').checked){let i=0;for(const c of result.drainage.catchments||[]){svg.append(geometryElement(c.geometry,{fill:`hsl(${i++*67%360},50%,55%)`,'fill-opacity':.2,stroke:'#476d73','stroke-width':view[2]/1000,'pointer-events':'none'}));}for(const p of result.drainage.flow_paths||[]){svg.append(geometryElement({type:'LineString',coordinates:p.coordinates},{fill:'none',stroke:'#266e9e','stroke-width':view[2]/900,'pointer-events':'none'}));}}
 for(const f of (result?.map_features||edits())){const p=f.properties;const type=p.layer==='surface'?p.class:p.layer;const color=colors[type]||'#789080';const shape=geometryElement(f.geometry,{fill:['barrier','connection'].includes(type)?'none':color,'fill-opacity':.38,stroke:String(f.id)===selected?'#fff':color,'stroke-width':view[2]/(String(f.id)===selected?300:600),'data-feature':f.id});shape.addEventListener('pointerdown',e=>{if($('tool').value==='select'){e.stopPropagation();selected=String(f.id);renderMap();showDetails();}});svg.append(shape);}
 renderAssessmentOverlays(svg);
 svg.append(geometryElement(current.parcel,{fill:'none',stroke:'#163f32','stroke-width':view[2]/400,'pointer-events':'none'}));
 const chosen=(result?.map_features||edits()).find(f=>String(f.id)===selected);if(chosen&&$('tool').value==='select'){coordinates(chosen.geometry).forEach((p,i)=>{const v=element('circle',{cx:p[0],cy:-p[1],r:view[2]/160,fill:'white',stroke:'#193e32','stroke-width':view[2]/700});v.addEventListener('pointerdown',e=>{e.stopPropagation();try{needReason();}catch(err){status(err.message,true);return;}drag={kind:'vertex',feature:structuredClone(chosen),index:i,start:[...p]};svg.setPointerCapture(e.pointerId);});svg.append(v);});}
 if(drawing.length){svg.append(geometryElement({type:'LineString',coordinates:drawing},{fill:'none',stroke:'#d35e31','stroke-width':view[2]/400,'pointer-events':'none'}));drawing.forEach(p=>svg.append(element('circle',{cx:p[0],cy:-p[1],r:view[2]/200,fill:'#d35e31','pointer-events':'none'})));}}
function mapPoint(event){const point=new DOMPoint(event.clientX,event.clientY).matrixTransform($('map').getScreenCTM().inverse());return [point.x,-point.y];}
$('map').addEventListener('pointerdown',e=>{if(!current)return;const tool=$('tool').value;if(tool!=='select'){drawing.push(mapPoint(e));if(tool==='inlet')action(finish);else renderMap();return;}drag={kind:'pan',point:mapPoint(e),view:[...view]};$('map').setPointerCapture(e.pointerId);});
$('map').addEventListener('pointermove',e=>{if(!drag)return;if(drag.kind==='pan'){const p=mapPoint(e);view[0]+=drag.point[0]-p[0];view[1]-=drag.point[1]-p[1];renderMap();}else{const p=mapPoint(e);let coords=coordinates(drag.feature.geometry);const original=coords[drag.index];let start=[...original];coords.forEach(v=>{if(v===original||(v[0]===start[0]&&v[1]===start[1])){v[0]=p[0];v[1]=p[1];}});renderMap();$('map').append(geometryElement(drag.feature.geometry,{fill:'none',stroke:'#d35e31','stroke-width':view[2]/250,'pointer-events':'none'}));}});
$('map').addEventListener('pointerup',()=>{if(!drag)return;const done=drag;drag=null;if(done.kind==='vertex'){const target=done.feature.id;change({action:'replace',target,feature:done.feature});selected=done.feature.id;renderMap();}});
$('map').addEventListener('wheel',e=>{if(!view)return;e.preventDefault();const p=mapPoint(e),scale=e.deltaY>0?1.15:1/1.15;view=[p[0]+(view[0]-p[0])*scale,-p[1]+(view[1]+p[1])*scale,view[2]*scale,view[3]*scale];renderMap();},{passive:false});
async function finish(){requireCase();needReason();const tool=$('tool').value;if(tool==='select')return;const line=['connection','barrier'].includes(tool);if(drawing.length<(tool==='inlet'?1:line?2:3))throw Error('Draw more vertices before finishing');const id=crypto.randomUUID();const properties={layer:['roof','pavement','pervious','unknown'].includes(tool)?'surface':tool,evidence:'manual_correction'};if(properties.layer==='surface')properties.class=tool;
 if(tool==='connection'){properties.from=prompt('Source collection-point ID, or a roof surface feature ID for a roof connection (select a feature to inspect its ID):');properties.to=prompt('Destination collection-point ID or named external outlet:');properties.evidence=prompt('Connection evidence: documented, scenario, or unknown','unknown');if(!properties.from||!properties.to)throw Error('Both connection endpoints are required');}
 const geometry={type:tool==='inlet'?'Point':line?'LineString':'Polygon',coordinates:tool==='inlet'?drawing[0]:line?drawing:[[...drawing,drawing[0]]]};
 if(tool==='benefit'){const category=prompt('Category: canopy, roof_disconnection, pavement_disconnection, open_space, management','canopy');if(!category)return;const evidence=JSON.parse(prompt('Evidence object; omitted prerequisites remain unknown','{}'));properties.benefit={id,category,area_sqft:0,evidence,basis:'modeled'};change({action:'add',feature:{type:'Feature',id,geometry,properties}});drawing=[];selected=id;$('tool').value='select';status('Credit geometry added. Supply evidence in case details and rerun.');renderMap();showDetails();return;}
 change({action:'add',feature:{type:'Feature',id,geometry,properties}});drawing=[];selected=id;$('tool').value='select';renderMap();showDetails();}
function showDetails(){if(!current)return;syncEvidenceLists();$('case-name').textContent=current.name;$('map-title').textContent=current.name;const f=edits().find(x=>String(x.id)===selected);$('inspect').textContent=f?JSON.stringify(f.properties,null,2)+'\nID: '+f.id:'Select a map feature.';$('source-info').innerHTML=`<p>${esc(current.crs)} · ${current.sources.length} source captures · ${current.corrections.length} corrections</p>`+'<details><summary>Source dates and snapshots</summary>'+current.sources.map(s=>`<p>${esc(s.url||s.source_url||s.path||'Local evidence')}<br>Retrieved ${esc(s.retrieved_at||s.retrieved_at_utc||'Unknown')}<br>Acquired ${esc(s.acquisition_date||'Unknown')}</p>`).join('')+'</details>';}
function renderResults(){offerRecompute();if(!result)return;renderResearch();renderModelSummary();if(!result.billing)return renderGisResults();const m=result.measurement;$('metrics').innerHTML=[['Gross area',m.ga_sqft,'sq ft · polygon consistency'],['Known physical IA',m.ia_sqft,'sq ft · '+(m.complete?'complete surface coverage':'partial surface coverage')],['Unknown surfaces',m.unknown_sqft,'sq ft · needs review'],['Observed tree canopy',m.canopy_sqft,'sq ft · '+(m.canopy_status==='complete'?'source coverage complete':m.canopy_status||'coverage unknown')+' · '+(m.canopy_source_vintage||'date unknown')]].map(([label,n,unit])=>`<div class="metric"><small>${esc(label)}</small><strong>${fmt(n)}</strong><span>${esc(unit)}</span></div>`).join('');const b=result.billing;let table=['baseline','appeal_only','credit_only','combined','documented_credit_only','documented_combined'].filter(k=>b[k]).map(k=>{const s=b[k];return `<tr><td>${esc(k.replaceAll('_',' '))}</td><td>${esc(s.status)}<br>${esc(s.basis||'')}</td><td>${s.monthly_total==null?'—':'$'+fmt(s.monthly_total)}</td><td>${s.annual_savings==null?'—':'$'+fmt(s.annual_savings)}</td><td>${esc((s.reasons||[]).join(' '))}</td></tr>`;}).join('');$('results').innerHTML=`<div class="result-card warning"><h3>Evidence gaps <span class="pill">Research screening</span></h3><ul>${result.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')}</ul></div><div class="result-card"><h3>Billing comparison</h3><table><tr><th>Scenario</th><th>Evidence basis</th><th>Monthly total</th><th>Annualized reduction</th><th>Blockers</th></tr>${table}</table><p>${esc(b.reason||'Annualized current-rate illustrations; actual bills and PWD approval remain separate.')}</p></div><div class="result-card"><h3>Separate independent validation</h3><p>IA: <strong>${esc(result.validation.ia.status)}</strong> · Drainage: <strong>${esc(result.validation.drainage.status)}</strong></p><details><summary>Metrics and reference blockers</summary><pre>${esc(JSON.stringify(result.validation,null,2))}</pre></details></div><div class="result-card"><h3>Routing & credit screens</h3><p>${result.drainage.catchments?.length||0} catchments · ${fmt(result.processing_seconds)} seconds processing · manual review ${fmt(current.manual_review_minutes)} minutes</p><details><summary>Catchment areas and missing prerequisites</summary><pre>${esc(JSON.stringify({catchments:(result.drainage.catchments||[]).map(({geometry,...x})=>x),screens:result.screens},null,2))}</pre></details><details><summary>Unknown-surface assumption scenarios</summary><pre>${esc(JSON.stringify(result.surface_assumption_scenarios,null,2))}</pre></details></div>`;renderAutomatic();renderAssessment();renderMap();}
function renderGisResults(){
 const m=result.measurement;const metric=(key)=>m[key+'_m2']??(m[key+'_sqft']==null?null:m[key+'_sqft']*.09290304);
 $('metrics').innerHTML=[['Boundary area','ga'],['Known impervious','ia'],['Unknown surfaces','unknown'],['Canopy / ground IA','canopy_ground_ia']].map(([name,key])=>`<div class="metric"><small>${name}</small><strong>${fmt(metric(key))}</strong><span>m² · ${key==='unknown'?'review required':'physical measurement'}</span></div>`).join('');
 $('results').innerHTML=`<div class="result-card warning"><h3>Evidence gaps <span class="pill">Physical GIS</span></h3><ul>${result.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')}</ul></div><div class="result-card"><h3>Terrain and drainage</h3><p>${esc(result.drainage.status)} · ${result.drainage.catchments?.length||0} terminal regions · ${fmt(result.processing_seconds)} seconds</p><p>Map/terrain ${esc(current.crs)} · area accounting ${esc(m.area_crs||current.crs)}. Unknown connections and ground surfaces remain explicit.</p><details><summary>Catchment areas and routing evidence</summary><pre>${esc(JSON.stringify((result.drainage.catchments||[]).map(({geometry,...x})=>x),null,2))}</pre></details></div><div class="result-card"><h3>Independent validation</h3><p>Surface measurement: ${esc(result.validation.ia.status)} · drainage: ${esc(result.validation.drainage.status)}</p><details><summary>Reference metrics and missing evidence</summary><pre>${esc(JSON.stringify(result.validation,null,2))}</pre></details></div>`;renderMap();
}
async function configure(){
 const c=await api('/api/config');document.body.dataset.mode=c.mode;document.title=c.title;
 savedViews=c.saved_views===true;
 if(c.mode==='gis'){$('app-scope').textContent='LOCAL GIS / DRAINAGE';$('app-title').textContent='GIS & drainage workbench';$('parcel-id').disabled=true;const credit=$('tool').querySelector('option[value="benefit"]');if(credit)credit.remove();$('details-description').textContent='Details include source dates, terrain units, construction and condition observations, roof/pipe connections, reference boundaries and logged review minutes.';status('Load a boundary or open the saved GIS project.');}else{$('app-scope').textContent='PHILADELPHIA / RESEARCH V1';$('app-title').textContent='Existing-site assessment';$('run').textContent='Run assessment';await refreshRenewals();}
}

async function run(){requireCase();status('Running local calculations…');result=await api('/api/analyze',{case:current});renderResults();showDetails();status(`Analysis complete. IA validation: ${result.validation.ia.status}; drainage validation: ${result.validation.drainage.status}.`);}
async function list(){const data=await api('/api/cases');$('cases').innerHTML=data.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');}
async function load(id){if(dirty&&!confirm('Discard unsaved edits and open this case?'))return;if(savedViews){const saved=await api('/api/saved/'+encodeURIComponent(id));current=saved.case;result=saved.analysis;selected=null;drawing=[];dirty=false;resetAssessmentEditor();fit();showDetails();if(result)renderResults();else{for(const key of ['metrics','automatic-results','modeled-results','assessment-results','results','research-results'])$(key).innerHTML='';}offerRecompute();exports();status((saved.saved_status?.message||'Saved case opened.')+(saved.saved_status?.assessment_as_of?' Assessment date: '+saved.saved_status.assessment_as_of+'.':''));return;}current=await api('/api/cases/'+encodeURIComponent(id));selected=null;drawing=[];dirty=false;resetAssessmentEditor();fit();await run();exports();}
function exports(){if(!current)return;const root='/exports/'+encodeURIComponent(current.id)+'/';$('exports').innerHTML=`<p><a href="${root}report.html" target="_blank">Evidence report</a> · <a href="${root}case.json" download>Case JSON</a><br><a href="${root}measurements.geojson" download>GeoJSON</a> · <a href="${root}analysis.json" download>Measurements JSON</a>${document.body.dataset.mode==='gis'?'':`<br><a href="${root}evidence-bundle.json" download>Portable evidence bundle</a>`}</p>`;}
$('open').onclick=()=>action(()=>load($('cases').value));$('run').onclick=()=>action(document.body.dataset.mode==='gis'?run:runAssessment);$('fit').onclick=fit;$('show-imagery').onchange=renderMap;$('show-drainage').onchange=renderMap;$('show-research').onchange=renderMap;$('show-modeled').onchange=renderMap;$('finish').onclick=()=>action(finish);$('cancel').onclick=()=>{drawing=[];renderMap();};$('tool').onchange=()=>{drawing=[];renderMap();};
$('delete').onclick=()=>action(async()=>{requireCase();if(!selected)throw Error('Select a feature');change({action:'delete',target:selected});selected=null;});$('undo').onclick=()=>action(async()=>{requireCase();current.corrections.pop();selected=null;dirty=true;result=null;renderMap();showDetails();status('Last correction removed from current revision; prior saved revisions remain. Rerun and save.');});
function offerRecompute(){const box=$('recompute-offer');if(!box)return;const q=result?.quality_review;const show=!!(q&&q.status==='outdated'&&q.recompute_available);box.hidden=!show;$('recompute-label').textContent=show?(q.label||'Saved results were calculated by an older interpretation version.'):'';}
$('recompute').onclick=()=>action(async()=>{requireCase();if(dirty&&!confirm('Recompute also saves your unsaved edits. Continue?'))return;status('Recomputing from saved inputs locally; no source refresh…');result=await api('/api/save',{case:current,recompute_gis:true});dirty=false;renderResults();showDetails();exports();await list();$('cases').value=current.id;status(result.quality_review?.status==='outdated'?'Recompute finished but results remain outdated: '+(result.quality_review.reason||''):'Recomputed from saved inputs with the current interpretation and saved.');});
$('save').onclick=()=>action(async()=>{requireCase();status('Saving frozen case and generating exports…');result=await api('/api/save',{case:current});dirty=false;renderResults();exports();await list();$('cases').value=current.id;if(document.body.dataset.mode!=='gis')await refreshRenewals();status('Case saved. Report, case JSON, analysis JSON and GeoJSON exports are ready.');});
async function assessProperty(query){
 if(dirty&&!confirm('Discard unsaved edits and assess another property?'))return;
 status('Acquiring the property, imagery, canopy, surfaces, terrain and public records…');
 const response=await api('/api/property/assess',{query});
 if(response.matches){$('property-matches').innerHTML=response.matches.length?'<p>Select the matching property:</p>'+response.matches.map(m=>`<button data-parcel-match="${esc(m.parcel_id)}">${esc(m.address)} · ${esc(m.parcel_id)}</button>`).join(''):'<p>No matching Philadelphia parcel. Try the street address or PWD parcel ID.</p>';for(const b of $('property-matches').querySelectorAll('[data-parcel-match]'))b.onclick=()=>action(()=>assessProperty(b.dataset.parcelMatch));status('Property selection needed; no assessment was saved.');return;}
 current=response.case;result=response.analysis;dirty=false;selected=null;drawing=[];$('property-matches').innerHTML='';fit();showDetails();renderResults();exports();await list();$('cases').value=current.id;await refreshRenewals();status('Automatic assessment saved. Review source dates, estimates and uncertainties.');$('automatic-results').scrollIntoView({behavior:'smooth',block:'start'});
}
$('acquire').onclick=()=>action(()=>assessProperty($('parcel-id').value.trim()));
$('edit-case').onclick=()=>{try{requireCase();$('case-json').value=JSON.stringify(current,null,2);$('editor').showModal();}catch(e){status(e.message,true);}};$('close-editor').onclick=()=>$('editor').close();$('apply-case').onclick=()=>action(async()=>{const next=JSON.parse($('case-json').value);const verified=await api('/api/analyze',{case:next});current=next;result=verified;dirty=true;selected=null;drawing=[];$('editor').close();fit();showDetails();renderResults();status('Case details updated. Save to retain this revision.');});
$('case-import').onchange=()=>action(async()=>{const f=$('case-import').files[0];if(!f)return;const next=JSON.parse(await f.text());if(document.body.dataset.mode!=='gis'&&next.attachments&&next.case){const imported=await api('/api/assessment/import',{bundle:next});current=imported.case;result=imported.analysis;}else{result=await api('/api/analyze',{case:next});current=next;}dirty=true;selected=null;resetAssessmentEditor();fit();showDetails();renderResults();status('Imported case evidence. Save & export to retain locally.');});
$('import-raster').onclick=()=>action(async()=>{requireCase();const f=$('raster').files[0];if(!f)throw Error('Choose a GeoTIFF');if(f.size>20*1024*1024)throw Error('Crop raster below 20 MB before import');status('Importing raster with explicit units and NoData…');const bytes=new Uint8Array(await f.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));const d=await api('/api/import-raster',{content:btoa(binary),kind:$('raster-kind').value,vertical_unit:$('vertical-unit').value,acquisition_date:$('acquisition-date').value||null,class_map:JSON.parse($('class-map').value),target_crs:current.crs});if(d.grid){if(d.grid.crs!==current.crs){if(document.body.dataset.mode!=='gis')throw Error('DEM CRS differs from case; align the case explicitly before import');current=await api('/api/align-case',{case:current,target_crs:d.grid.crs});fit();}current.terrain=d.grid;}else current.features.features.push(...d.features.features);current.sources.push(d.provenance);current.warnings=[...(current.warnings||[]),...d.warnings];dirty=true;await run();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
action(async()=>{await configure();await list();const params=new URLSearchParams(location.search);if(document.body.dataset.mode!=='gis'&&params.has('prospect')){const pid=params.get('prospect');$('parcel-id').value=/^\d+$/.test(pid)?pid:'';status('Prospect selected. Choose Assess property when ready to run imagery and the full assessment.');return;}const requested=params.get('case');if(requested&&[...$('cases').options].some(o=>o.value===requested))$('cases').value=requested;if($('cases').value)await load($('cases').value);});

$('boundary-import').onchange=()=>action(async()=>{const f=$('boundary-import').files[0];if(!f)return;if(dirty&&!confirm('Discard unsaved edits and load a new boundary?'))return;status('Importing analysis boundary…');current=await api('/api/import-boundary',{geojson:JSON.parse(await f.text()),crs:$('boundary-crs').value.trim()||null,name:f.name.replace(/\.[^.]+$/,'')});result=null;selected=null;drawing=[];dirty=true;fit();await run();});
$('features-import').onchange=()=>action(async()=>{requireCase();const f=$('features-import').files[0];if(!f)return;const d=await api('/api/import-features',{geojson:JSON.parse(await f.text()),crs:$('features-crs').value.trim()||null,target_crs:current.crs});const ids=new Set(current.features.features.map(f=>String(f.id)));if(d.features.some(f=>ids.has(String(f.id))))throw Error('Feature IDs already exist in this project; use distinct IDs or edit the existing observations.');current.features.features.push(...d.features);current.sources.push(d.provenance);dirty=true;await run();});

const assessmentLabels={green_roof:'Existing green roofs',permeable_pavement:'Existing permeable pavement',direct_discharge:'Direct surface-water discharge',industrial_npdes:'Industrial NPDES',prior_credits:'Prior credits and renewals'};
const commonFactFields=[['existing_installation','Existing installation confirmed'],['account_current','Account current'],['physical_area_confirmed','Physical managed area confirmed'],['parcel_allocation_confirmed','Parcel allocation confirmed']];
const systemFactFields=[['routing_confirmed','Contributing drainage confirmed'],['approved_record_drawings','Approved record drawings'],['current_condition_confirmed','Current condition confirmed'],['maintenance_documented','Maintenance documented'],['professional_reviewed','Professional review documented'],['treatment_depth_inches','Treatment depth (inches)','number']];
const assessmentFactFields={
 green_roof:[...commonFactFields,...systemFactFields],
 permeable_pavement:[...commonFactFields,...systemFactFields,['material_confirmed','Permeable material confirmed'],['construction_documented','Construction documented'],['storage_documented','Storage documented'],['infiltration_or_underdrain_documented','Infiltration / underdrain documented']],
 direct_discharge:[...commonFactFields,['catchment_confirmed','Catchment confirmed'],['route_confirmed','Conveyance route confirmed'],['private_connections_resolved','Private connections resolved'],['outfall_confirmed','Outfall confirmed'],['destination_confirmed','Receiving surface water confirmed'],['no_city_infrastructure','No City infrastructure used'],['ownership_confirmed','Infrastructure ownership confirmed'],['no_erosion_or_detriment','No erosion or detrimental impacts'],['site_plan_documented','Site plan documented'],['photographs_current','Current photographs'],['waterway_name','Receiving waterway name','text'],['outfall_id','Outfall identifier','text'],['upstream_smp_present','Upstream management system present'],['upstream_smp_compliant','Upstream system compliant'],['upstream_smp_functional','Upstream system functional']],
 industrial_npdes:[['account_current','Account current'],['site_match','Permit site identity matches'],['operator_match','Permit operator identity matches'],['industrial_stormwater','Industrial stormwater coverage'],['active','Coverage active'],['compliance_previous_12_months','Previous 12 months compliance documented'],['permit_documented','Permit document available'],['discharge_monitoring_reports_previous_12_months','Previous 12 months monitoring reports available'],['permit_id','Permit ID','text'],['effective_from','Coverage effective date','date'],['expires_on','Coverage expiry date','date'],['permit_type','Permit type (industrial, construction, municipal, no_exposure or terminated)','text'],['compliance_from','Compliance evidence starts','date'],['compliance_through','Compliance evidence through','date']]
};
const factHelp={green_roof:'A planted roof image or proposed project alone does not confirm an installed system. Keep footprint and managed drainage separate.',permeable_pavement:'Appearance alone does not establish permeability. Record construction, storage, drainage and maintenance evidence; physical IA is retained.',direct_discharge:'A downhill route or proximity to water is a candidate only. Establish the complete conveyance, outfall and ownership path.',industrial_npdes:'Construction permits, name-only matches and a lack of public violations do not establish qualifying industrial coverage or compliance.'};
const money=n=>n==null?'Unknown':'$'+Number(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
function assessmentRecords(){return current?.assessment?.records||[];}
function currentAssessmentRecord(){return assessmentRecords().find(r=>String(r.id)===$('assessment-record').value);}
function syncEvidenceLists(){
 if(!current||document.body.dataset.mode==='gis')return;
 const selectedRecord=$('assessment-record').value;
 $('assessment-record').innerHTML='<option value="">New manual record</option>'+assessmentRecords().map(r=>`<option value="${esc(r.id)}">${esc(assessmentLabels[r.category]||r.category)} · ${esc(r.decision||'candidate')} · ${esc(r.id)}</option>`).join('');
 if(assessmentRecords().some(r=>String(r.id)===selectedRecord))$('assessment-record').value=selectedRecord;
 const identifiers=current.assessment?.identifiers||{};for(const key of ['permit_id','operator_name','site_name','street_address'])$('search-'+key.replaceAll('_','-')).value=identifiers[key]||'';$('renewal-lead-days').value=current.assessment?.renewal_lead_days??90;
 const attachments=current.assessment?.attachments||[];
 for(const id of ['assessment-document','history-document']){const chosen=$(id).value;$(id).innerHTML='<option value="">No document selected</option>'+attachments.map(a=>`<option value="${esc(a.id||a.sha256)}">${esc(a.filename||a.name||a.id||a.sha256)}</option>`).join('');if(attachments.some(a=>String(a.id||a.sha256)===chosen))$(id).value=chosen;}
 $('assessment-attachments').innerHTML=attachments.length?attachments.map(a=>`<p><a href="/api/attachment/${encodeURIComponent(current.id)}/${encodeURIComponent(a.sha256||a.id)}" download>${esc(a.filename||a.name||'Document')}</a><br><small>SHA-256 ${esc(a.sha256||'Unknown')} · ${fmt(a.size_bytes??a.size)} bytes</small></p>`).join(''):'<p>No documents attached.</p>';
 if(!$('assessment-facts').children.length)renderFactFields({});
}
function renderFactFields(facts){
 const category=$('assessment-category').value;
 $('assessment-facts').innerHTML=`<p>${esc(factHelp[category]||'')}</p><details open><summary>Facts and prerequisites</summary>`+(assessmentFactFields[category]||[]).map(([name,label,type])=>type?`<label>${esc(label)}<input data-fact="${esc(name)}" type="${esc(type)}" ${type==='number'?'min="0" step="any"':''} value="${esc(facts[name]??'')}" placeholder="Unknown"></label>`:`<label>${esc(label)}<select data-fact="${esc(name)}"><option value="">Unknown</option><option value="true" ${facts[name]===true?'selected':''}>Yes, supported by review</option><option value="false" ${facts[name]===false?'selected':''}>No</option></select></label>`).join('')+'</details>';
}
function readFactFields(){
 const facts={...(currentAssessmentRecord()?.facts||{})};
 for(const field of $('assessment-facts').querySelectorAll('[data-fact]')){const value=field.value;facts[field.dataset.fact]=value===''?null:field.tagName==='SELECT'?value==='true':field.type==='number'?Number(value):value;}
 return facts;
}
function resetAssessmentEditor(){
 if($('assessment-support-reviewed'))$('assessment-support-reviewed').checked=false;
 $('assessment-record').value='';$('assessment-decision').value='candidate';$('assessment-basis').value='manual';$('assessment-area').value='';$('assessment-page').value='';$('assessment-url').value='';$('assessment-reason').value='';$('assessment-extra').value='{}';assessmentGeometry=null;assessmentFootprint=null;renderFactFields({});showAssessmentGeometry();
}
function showAssessmentGeometry(){$('assessment-geometry').textContent=`Managed region: ${assessmentGeometry?'selected':'unknown'} · physical footprint: ${assessmentFootprint?'selected':'unknown'}. Geometries use the case map coordinates.`;}
function loadAssessmentRecord(){
 if($('assessment-support-reviewed'))$('assessment-support-reviewed').checked=false;
 const record=currentAssessmentRecord();if(!record){resetAssessmentEditor();return;}
 $('assessment-category').value=record.category;$('assessment-decision').value=record.decision||'candidate';$('assessment-basis').value=record.basis||'manual';$('assessment-area').value=record.managed_area_sqft??'';
 renderFactFields(record.facts||{});assessmentGeometry=record.geometry||null;assessmentFootprint=record.footprint_geometry||null;showAssessmentGeometry();
 const {id,category,decision,basis,facts,geometry,footprint_geometry,managed_area_sqft,...extra}=record;$('assessment-extra').value=JSON.stringify(extra,null,2);$('assessment-page').value='';$('assessment-url').value='';$('assessment-reason').value='';$('assessment-document').value='';
}
function evidenceReference(documentId,pageId,urlId){const attachment_id=$(documentId).value,page=$(pageId).value.trim(),source_url=$(urlId).value.trim();if(!attachment_id&&!source_url){if(page)throw Error('Choose a supporting document or source URL for the page reference');return null;}if(source_url&&!/^https?:\/\//i.test(source_url))throw Error('Use an http or https source URL');if(page&&(!Number.isInteger(Number(page))||Number(page)<1))throw Error('Document page number must be a positive whole number');return {...(attachment_id?{attachment_id}:{}),...(page?{page:Number(page)}:{}),...(source_url?{source_url}:{})};}
async function saveAssessmentRecord(){
 requireCase();const reason=$('assessment-reason').value.trim();if(!reason)throw Error('Enter a review explanation so earlier evidence remains traceable');
 const extra=JSON.parse($('assessment-extra').value||'{}');if(!extra||Array.isArray(extra)||typeof extra!=='object')throw Error('Additional record details must be an object');
 const reference=evidenceReference('assessment-document','assessment-page','assessment-url');const existing=currentAssessmentRecord();const record={...extra,id:existing?.id||crypto.randomUUID(),category:$('assessment-category').value,decision:$('assessment-decision').value,basis:$('assessment-basis').value,facts:readFactFields(),evidence_refs:[...(extra.evidence_refs||[]),...(reference?[reference]:[])]};
 if($('assessment-support-reviewed').checked){record.evidence_review={support_reviewed:true,property_match:true,period_match:true,fact_keys:Object.keys(record.facts).filter(k=>record.facts[k]!=null),note:reason};}else delete record.evidence_review;
 if($('assessment-area').value!=='')record.managed_area_sqft=Number($('assessment-area').value);if(assessmentGeometry)record.geometry=assessmentGeometry;if(assessmentFootprint)record.footprint_geometry=assessmentFootprint;
 const response=await api('/api/assessment/review',{case:current,record,reason});current=response.case;result=response.analysis;dirty=true;showDetails();$('assessment-record').value=record.id;loadAssessmentRecord();renderResults();status('Review recorded with earlier evidence retained. Save & export to retain the case.');
}
async function runAssessment(){
 requireCase();current.assessment??={};current.assessment.identifiers??={};for(const key of ['permit_id','operator_name','site_name','street_address']){const v=$('search-'+key.replaceAll('_','-')).value.trim();if(v)current.assessment.identifiers[key]=v;else delete current.assessment.identifiers[key];}status('Gathering available public records and assessing existing conditions…');const response=await api('/api/assessment/run',{case:current});current=response.case;result=response.analysis;dirty=false;showDetails();renderResults();exports();await list();$('cases').value=current.id;await refreshRenewals();status('Assessment snapshot saved. Review category findings, source gaps and renewal warnings below.');
}
function renewalTable(rows){
 if(!rows?.length)return '<p>No credit history recorded. Award status and renewal dates are unknown.</p>';
 return `<div class="table-scroll"><table><tr><th>Credit / category</th><th>Renewal state</th><th>Known deadline</th><th>Evidence gaps</th></tr>${rows.map(r=>`<tr><td>${esc(r.credit_id||r.id||'Unknown')}<br>${esc(r.category||'Unknown category')}</td><td><strong>${esc((r.status||'unknown_dates').replaceAll('_',' '))}</strong>${r.days_remaining==null?'':`<br>${fmt(r.days_remaining)} days remaining`}</td><td>${esc(r.deadline||'Unknown')}</td><td>${esc([...(r.missing||[]),...(r.warnings||[])].join('; ')||'None recorded')}</td></tr>`).join('')}</table></div>`;
}
async function refreshRenewals(){
 if(document.body.dataset.mode==='gis')return;
 const data=await api('/api/renewals');$('renewal-overview').innerHTML=`<p>As of ${esc(data.as_of||'today')} · reminder lead time ${fmt(data.lead_days??90)} days.</p>`+(data.properties||[]).map(p=>`<details><summary><a href="/?case=${encodeURIComponent(p.id)}">${esc(p.name||p.id)}</a></summary>${p.error?`<p class="error">Saved evidence could not be evaluated: ${esc(p.error)}</p>`:renewalTable(p.renewals)}<p>Reminder lead time: ${fmt(p.lead_days??data.lead_days??90)} days.</p></details>`).join('')+(!(data.properties||[]).length?'<p>No saved properties.</p>':'');
}
function curveNumberHtml(w){
 if(!w)return '';
 const show=v=>v==null?'Unknown':fmt(v);
 const rows=(w.rows||[]).map(r=>`<tr><td>${esc(r.feature_id)}<br>${esc(r.basis.replaceAll('_',' '))}</td><td>${show(r.area_sqft)}</td><td>${esc(r.cover||'Unknown')} / ${esc(r.condition||'Unknown')}<br>${esc(r.image_class||'')}</td><td>${esc(r.soil_group||'Unknown')}<br>${esc(r.mapunit_name||'No soil map coverage')}<br>Map unit ${esc(r.mapunit_key||'Unknown')}</td><td>${show(r.curve_number)}<br>Candidate range: ${show(r.candidate_cn_min)}–${show(r.candidate_cn_max)}</td><td>${show(r.area_times_cn)}</td><td>${esc(r.missing.join('; ')||'Conditional inputs; site verification required')}<br>${esc(r.input_basis||'')}</td></tr>`).join('');
 const ids=[...new Set((w.rows||[]).filter(r=>!['conflicting-open-space','unattributed-open-space'].includes(r.feature_id)).map(r=>r.feature_id))];
 const covers=['lawn','meadow','athletic_field','porous_turf','brush','woods_grass','woods','gravel','dirt','water'];
 return `<div class="result-card"><h3>Open-space curve-number worksheet</h3><p>${esc(w.claim)}</p><p><strong>Property open-space CN: ${show(w.average_cn)}</strong> · Mapped open-space average: ${show(w.mapped_open_space_average_cn)} · Known portion only: ${show(w.known_portion_average_cn)}</p><p>Mapped open space: ${show(w.mapped_open_space_sqft)} sq ft; missing CN inputs: ${show(w.unknown_cn_area_sqft)} sq ft. Image candidates: ${show(w.image_candidate_area_sqft)} sq ft. Unresolved ground: ${show(w.unresolved_ground_sqft)} sq ft.</p><p>${esc(w.formula)}. Standard credit factor: ${w.credit_factor==null?'Unknown':show(w.credit_factor*100)+'%'}. ${esc(w.rounding)}</p><ul>${(w.issues||[]).map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><div class="table-scroll"><table><tr><th>Mapped area / basis</th><th>Area (sq ft)</th><th>Cover / condition</th><th>Soil group / map unit</th><th>CN</th><th>Area × CN</th><th>Unknowns / evidence</th></tr>${rows||'<tr><td colspan="7">Open-space cover is unknown. No zero area or credit is inferred.</td></tr>'}</table></div>${ids.length?`<details><summary>Review cover and condition inputs</summary><p>These manual inputs remain conditional. Source geometry and soil records are preserved.</p><label>Mapped area<select id="cn-feature">${ids.map(id=>'<option value="'+esc(id)+'">'+esc(id)+'</option>').join('')}</select></label><label>PWD cover<select id="cn-cover"><option value="">Unknown</option>${covers.map(c=>'<option value="'+c+'">'+c.replaceAll('_',' ')+'</option>').join('')}</select></label><label>Condition<select id="cn-condition"><option value="">Unknown / not applicable</option><option>poor</option><option>fair</option><option>good</option></select></label><label>Evidence / reason<input id="cn-reason" placeholder="Describe the source and current condition"></label><button id="cn-save-inputs">Apply reviewed inputs</button></details>`:''}<details><summary>Soil components, source requests, dates and reproducible hashes</summary><pre>${esc(JSON.stringify(w,null,2))}</pre></details></div>`;
}
function renderAssessment(){
 if(document.body.dataset.mode==='gis')return;
 const a=result?.assessment;if(!a){$('assessment-results').innerHTML='<div class="result-card"><h3>Existing-site assessment</h3><p>No assessment snapshot is available. Use Run assessment to gather public candidates and assess the five categories.</p></div>';return;}
 const categories=Array.isArray(a.categories)?a.categories:Object.values(a.categories||{});
 const categoryCards=categories.map(c=>`<div class="result-card"><h3>${esc(c.label||assessmentLabels[c.category]||c.category)} <span class="pill">${esc((c.status||'unknown').replaceAll('_',' '))}</span></h3>${c.modeled_context?'<p>'+esc(c.modeled_context.claim)+'</p><details><summary>AI and drainage context</summary><pre>'+esc(JSON.stringify(c.modeled_context,null,2))+'</pre></details>':''}${c.category==='prior_credits'?renewalTable(c.renewals||a.renewals):(c.records||[]).length?c.records.map(r=>`<div class="assessment-record-result"><p><strong>${esc(r.id)}</strong> · ${esc((r.status||'unknown').replaceAll('_',' '))} · ${esc(r.basis||'unknown basis')}<br>Managed area: ${fmt(r.managed_area_sqft)} sq ft · footprint: ${fmt(r.footprint_area_sqft)} sq ft</p><p>${esc([...(r.missing||[]).map(v=>'Missing: '+v),...(r.failed||[]).map(v=>'Failed: '+v)].join('; ')||r.decision||'Review findings and evidence references.')}</p>${modeledRecordHtml(r.modeled_context)}<button data-review-record="${esc(r.id)}">Review / correct record</button><details><summary>Evidence and rule findings</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details></div>`).join(''):`<p>${esc(c.reason||'No supported record. Evidence remains unknown; this does not establish that the feature or coverage is absent.')}</p>`}</div>`).join('');
 const economics=a.economics||{};const scenarioKeys=['measurement_only','documented','modeled','documented_combined','modeled_combined'];const economicsRows=scenarioKeys.filter(k=>economics[k]).map(k=>{const v=economics[k];return `<tr><td>${esc(k==='baseline'?'Existing baseline':({measurement_only:'Physical measurement correction only',documented:'Documented-record credits only',modeled:'Conditional modeled credits only',documented_combined:'Documented-record credits with measurement correction',modeled_combined:'Conditional credits with measurement correction'})[k]||k)}</td><td>${esc(v.status||'unknown')}<br>${esc(v.basis==='conditional'?'Conditional estimate':v.basis==='documented'?'Documented evidence basis':'Evidence basis unknown')}</td><td>${money(v.gross_monthly_reduction)}</td><td>${money(v.gross_annual_reduction)}</td><td>${esc([...(v.reasons||[]),...(v.assumptions||[]),v.reason||''].filter(Boolean).join('; '))}</td></tr>`;}).join('');
 const sourceRows=(a.source_status||current.assessment?.source_status||[]).map(s=>`<li>${esc(s.provider||s.source||s.category||'Public source')}: ${esc(s.status||'unknown')}${s.retrieved_at||s.attempted_at?' · '+esc(s.retrieved_at||s.attempted_at):''} ${esc([s.reason||s.error||s.message||'',...(s.errors||[]),s.coverage||''].filter(Boolean).join('; '))}</li>`).join('');
 $('assessment-results').innerHTML=`<div class="assessment-grid">${categoryCards}</div><div class="result-card"><h3>Gross ongoing bill reductions</h3><p>Existing baseline monthly charge: ${money(economics.baseline?.monthly_total)}. One reconciled ledger preserves existing benefits. Conditional values require the stated evidence; annual values are current-rate illustrations.</p><div class="table-scroll"><table><tr><th>Evidence basis</th><th>Status</th><th>Monthly gross reduction</th><th>Annual gross reduction</th><th>Blockers</th></tr>${economicsRows||'<tr><td colspan="5">Unknown — billing baseline or prerequisites missing.</td></tr>'}</table></div><details><summary>Bill and allocation ledger</summary><pre>${esc(JSON.stringify(economics,null,2))}</pre></details></div>${curveNumberHtml(a.open_space_curve_number)}${modeledCombinedHtml(a.modeled_integration)}<div class="result-card"><h3>Credit history and renewal warnings</h3>${renewalTable(a.renewals)}${publicCreditObservations(a.public_credit_observations)}<details><summary>History records and source dates</summary><pre>${esc(JSON.stringify(current.assessment?.credit_history||[],null,2))}</pre></details></div><div class="result-card warning"><h3>Possible historical billing issues for review</h3><p>These flags are separate from ongoing reductions. They do not establish a refund entitlement.</p>${(a.historical_flags||[]).length?(a.historical_flags||[]).map(f=>`<p>${esc(f.description||f.reason||f.kind||f.type||'Review discrepancy')}</p><pre>${esc(JSON.stringify(f,null,2))}</pre>`).join(''):'<p>No supported discrepancy identified. Incomplete bills or credit records may prevent review.</p>'}</div><div class="result-card"><h3>Public-record coverage and snapshots</h3><ul>${sourceRows||'<li>No public acquisition status recorded.</li>'}</ul><p>${fmt(current.assessment?.snapshots?.length||0)} saved assessment snapshots. Earlier observations, review decisions and document hashes are retained.</p><details><summary>Rule and source provenance</summary><pre>${esc(JSON.stringify({rules:a.rules,source_status:a.source_status||current.assessment?.source_status,snapshots:current.assessment?.snapshots},null,2))}</pre></details></div>`;
 if(a.baseline_refresh?.status==='pending_review'){
  const p=a.baseline_refresh;const rows=p.fields_changed.map(k=>`<tr><td>${esc(k.replaceAll('_',' '))}</td><td>${esc(JSON.stringify(current.baseline?.[k]??null))}</td><td>${esc(JSON.stringify(p.candidate[k]??null))}</td></tr>`).join('');
  $('assessment-results').insertAdjacentHTML('afterbegin',`<div class="result-card warning"><h3>Public billing changes need review</h3><p>Savings are blocked. Earlier billing evidence is preserved. Choose the baseline supported by your evidence.</p><table><tr><th>Field</th><th>Retained</th><th>New public record</th></tr>${rows}</table><label>Evidence / reason<input id="baseline-review-reason"></label><button id="baseline-use-public">Use public baseline</button><button id="baseline-retain">Retain earlier baseline</button></div>`);
  for(const [id,accept] of [['baseline-use-public',true],['baseline-retain',false]])$(id).onclick=()=>action(async()=>{const reason=$('baseline-review-reason').value.trim();if(!reason)throw Error('Explain which evidence supports the baseline');const response=await api('/api/assessment/baseline-review',{case:current,reason,accept});current=response.case;result=response.analysis;dirty=true;renderResults();status('Baseline review recorded using frozen GIS. Save to retain; no property acquisition or routing performed.');});
 }
 const cnFeature=$('cn-feature');if(cnFeature){cnFeature.onchange=()=>{const row=(a.open_space_curve_number?.rows||[]).find(r=>r.feature_id===cnFeature.value);$('cn-cover').value=row?.cover||'';$('cn-condition').value=row?.condition==='na'?'':row?.condition||'';$('cn-reason').value=row?.review?.reason||'';};cnFeature.onchange();}
 const cnSave=$('cn-save-inputs');if(cnSave)cnSave.onclick=()=>action(async()=>{const response=await api('/api/curve-number/review',{case:current,feature_id:$('cn-feature').value,cover:$('cn-cover').value,condition:$('cn-condition').value,reason:$('cn-reason').value});current=response.case;result=response.analysis;dirty=true;showDetails();renderResults();status('Curve-number inputs recorded. Save & export to retain the worksheet and review history.');});
 for(const button of $('assessment-results').querySelectorAll('[data-review-record]'))button.onclick=()=>{$('assessment-record').value=button.dataset.reviewRecord;loadAssessmentRecord();$('evidence-review').open=true;$('assessment-evidence').scrollIntoView({behavior:'smooth',block:'start'});};
}
$('assessment-category').onchange=()=>renderFactFields({});$('assessment-record').onchange=loadAssessmentRecord;$('assessment-save-record').onclick=()=>action(saveAssessmentRecord);
for(const [id,role] of [['assessment-use-region','region'],['assessment-use-footprint','footprint']])$(id).onclick=()=>action(async()=>{requireCase();const feature=edits().find(f=>String(f.id)===selected);if(!feature||!['Polygon','MultiPolygon'].includes(feature.geometry.type))throw Error('Select a polygon on the map first');if(role==='region')assessmentGeometry=structuredClone(feature.geometry);else assessmentFootprint=structuredClone(feature.geometry);showAssessmentGeometry();});
$('assessment-attach').onclick=()=>action(async()=>{requireCase();const file=$('assessment-upload').files[0];if(!file)throw Error('Choose a supporting document');if(file.size>16*1024*1024)throw Error('Choose a supporting document no larger than 16 MB');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=16384)binary+=String.fromCharCode(...bytes.subarray(i,i+16384));const response=await api('/api/assessment/attachment',{case:current,filename:file.name,content:btoa(binary)});current=response.case;dirty=true;syncEvidenceLists();$('assessment-document').value=response.attachment.id||response.attachment.sha256;status('Document attached with its original bytes and hash. Add facts and a page reference, then save the case.');});
$('history-add').onclick=()=>action(async()=>{requireCase();const credit_id=$('history-credit-id').value.trim(),reason=$('history-notes').value.trim();if(!credit_id)throw Error('Enter a credit or award identifier');if(!reason)throw Error('Enter a note identifying the evidence for this event');const ref=evidenceReference('history-document','history-page','history-url');const event={id:crypto.randomUUID(),credit_id,category:$('history-category').value.trim()||'unknown',status:$('history-event').value,evidence_refs:ref?[ref]:[],notes:reason};for(const [id,key] of [['history-effective','effective_from'],['history-expiry','expires_on'],['history-renewal','renewal_due'],['history-terminated','terminated_on'],['history-supersedes','supersedes']])if($(id).value)event[key]=$(id).value;if($('history-area').value!=='')event.credited_area_sqft=Number($('history-area').value);const response=await api('/api/assessment/history',{case:current,event,reason});current=response.case;result=response.analysis;dirty=true;showDetails();renderResults();status('History event added. Earlier events remain available. Save & export to retain the case.');});
