function renderAssessmentOverlays(svg){
 if(document.body.dataset.mode==='gis'||!current||!view)return;
 for(const record of assessmentRecords()){
  if(record.decision==='rejected')continue;
  const overlays=[['managed region',record.geometry,'#693b90',false],['physical footprint',record.footprint_geometry,'#b44e80',false],['public candidate '+(record.public_geometry_role||'location'),record.source?.crs===current.crs?record.public_geometry:null,'#147c9b',true]];
  for(const [label,geometry,color,candidate] of overlays){
   if(!geometry)continue;
   try{
    const overlay=geometryElement(geometry,{fill:color,'fill-opacity':candidate?0.04:0.07,stroke:color,'stroke-width':view[2]/450,'stroke-dasharray':candidate?`${view[2]/200} ${view[2]/250}`:'none','data-assessment-record':record.id,'pointer-events':$('tool').value==='select'?'visiblePainted':'none'});
    const title=element('title');title.textContent=`${assessmentLabels[record.category]||record.category}: ${label} · ${record.decision||'candidate'}. Assessment overlay; physical surface accounting is unchanged.`;overlay.append(title);
    overlay.addEventListener('pointerdown',event=>{if($('tool').value!=='select')return;event.stopPropagation();$('assessment-record').value=record.id;loadAssessmentRecord();$('evidence-review').open=true;$('assessment-evidence').scrollIntoView({behavior:'smooth',block:'start'});});svg.append(overlay);
   }catch(_error){/* Malformed source geometry remains in evidence; skip map decoration. */}
  }
 }
}
$('assessment-use-public-footprint').onclick=()=>action(async()=>{const record=currentAssessmentRecord();if(!record?.public_geometry||record.source?.crs!==current.crs||!['Polygon','MultiPolygon'].includes(record.public_geometry.type)||!String(record.public_geometry_role).includes('footprint'))throw Error('Select a public system candidate with a polygon footprint in the case map coordinates');assessmentFootprint=structuredClone(record.public_geometry);showAssessmentGeometry();status('Public polygon selected as a reviewed footprint. Managed drainage and installed-system evidence remain separate.');});

function publicCreditObservations(observations){
 if(!observations?.length)return '';
 return '<h4>Public credit flags — unverified observations</h4>'+observations.map(o=>`<div class="public-credit-observation"><p>Credits flag: <strong>${fmt(o.credits_flag)}</strong> · Expired flag: <strong>${fmt(o.expired_flag)}</strong> · Appeals flag: <strong>${fmt(o.appeals_flag)}</strong></p><p>Retrieved: ${esc(o.retrieved_at||'Unknown')}<br>Source: ${esc(o.source_url||'Unknown')}<br>Effective date: ${esc(o.effective_date||'Unknown')} · Expiry date: ${esc(o.expiry_date||'Unknown')}</p><p>${esc(o.interpretation||'Public flags do not establish an award, lapse, renewal deadline or refund entitlement.')}</p>${(o.missing_evidence||[]).length?'<ul>'+o.missing_evidence.map(m=>'<li>'+esc(m)+'</li>').join('')+'</ul>':''}</div>`).join('');
}

function renderAutomatic(){
 const a=result?.automatic,node=$('automatic-results');if(!a){node.innerHTML='';return;}
 const m=result.measurement;const rows=(a.estimates||[]).map(x=>`<tr><td>${esc(x.feature.replaceAll('_',' '))}</td><td>${fmt(x.area_sqft)}</td><td>${fmt(x.edge_lower_sqft)}–${fmt(x.edge_upper_sqft)}</td><td>${esc(x.source_vintage)}<br>${esc(x.basis||'')}</td></tr>`).join('');
 const billingRows=Object.entries(result.surface_assumption_scenarios||{}).map(([key,v])=>{const b=v.appeal||{};return `<tr><td>${esc(key.replaceAll('_',' '))}</td><td>${money(b.monthly_savings)}</td><td>${money(b.annual_savings)}</td><td>${esc((b.reasons||[]).join('; ')||v.reason||'Conditional current-rate illustration')}</td></tr>`;}).join('');
 const coverage=a.landcover;const failures=(a.source_status||[]).map(s=>`<li>${esc(s.provider)}: ${esc(s.status)} ${esc(s.error||s.claim||'')} ${s.source_vintage?'· '+esc(s.source_vintage):''}</li>`).join('');
 node.innerHTML=`<div class="result-card"><h2>Automatic site estimates</h2><p>${esc(a.claim)}</p><p>Assessment date: ${esc(a.imagery_age_policy?.as_of||a.at||'Historical snapshot')}. Cutoff: ${esc(a.imagery_age_policy?.cutoff||'Legacy assessment—rerun to apply the three-year limit')}. Unknown capture years are excluded. Earlier results remain historical.</p><table><tr><th>Feature</th><th>Source area (sq ft)</th><th>Pixel-edge sensitivity range</th><th>Source year</th></tr>${rows||'<tr><td colspan="4">Land-cover acquisition unavailable; canopy and ground cover remain unknown.</td></tr>'}</table><p>Ranges show pixel-edge and coverage sensitivity, not statistical confidence or present-day accuracy. Only satellite/aerial imagery within three years of the assessment date is used. Other datasets retain their own validity rules. Image-derived canopy and surface areas are modeled; independent local accuracy is unverified. If the local classifier is unavailable, only RGB cover candidates are shown.</p><p>Unresolved image cover area: ${fmt(coverage?.unclassified_sqft)} sq ft. Physical IA after source reconciliation: ${fmt(m.ia_min_sqft)}–${fmt(m.ia_max_sqft)} sq ft. Canopy over identified ground IA: ${fmt(m.canopy_ground_ia_sqft)}–${fmt(m.canopy_ground_ia_upper_sqft)} sq ft; hidden ground stays uncertain.</p><ul>${failures}</ul><p>${esc(coverage?.coverage_warning||'')}</p><p>Image vegetation candidates: ${fmt(a.image_vegetation_candidate_sqft)} sq ft (includes grass, trees and other green objects). Vegetation-on-roof candidate area: ${fmt(a.roof_vegetation_candidate_sqft)} sq ft. Image vegetation overlapping observed canopy: ${fmt(a.image_green_overlap_historical_canopy_sqft)} sq ft. Leaf-off conditions, shadows and site changes limit comparison. Greenness can be overhanging trees or coatings; it does not confirm a green roof. Pavement appearance does not establish permeability.</p>${billingRows?`<h3>Conditional billing estimates for unresolved surfaces</h3><p>Extreme ground-cover assumptions, not confidence limits or confirmed bill savings. Negative reductions mean a modeled bill increase. Current tariff and recorded baseline; actual bills and existing-credit reconciliation remain separate.</p><table><tr><th>Assumption</th><th>Gross monthly change</th><th>Gross annual change</th><th>Limitations</th></tr>${billingRows}</table>`:''}<details><summary>Automatically measured public systems</summary><pre>${esc(JSON.stringify((a.system_footprints||[]).map(({geometry,...x})=>x),null,2))}</pre></details><details><summary>Algorithms, source dates, hashes and coverage</summary><pre>${esc(JSON.stringify({age_policy:a.imagery_age_policy,settings:coverage?.settings,sources:coverage?.source_snapshots,image_method:a.image_method,model_unavailable:coverage?.model_unavailable,prediction_sha256:coverage?.prediction_sha256,warnings:a.warnings},null,2))}</pre></details></div>`;
}

function renderResearch(){
 const host=$('research-results');if(!host)return;const r=result?.research_drainage,p=r?.primary;
 if(!p){host.innerHTML=r?`<div class="result-card"><h3>Villanova/Temple additional analysis</h3><p>${esc(r.reason||r.status)}</p></div>`:'';return;}
 const runs=[['Nominal',p],...(r.sensitivity||[]).map(v=>[v.name,v])];
 const rows=runs.map(([name,v])=>`<tr><td>${esc(name)}</td><td>${fmt(v.grid.cell_size)} ${esc(v.grid.horizontal_unit)}</td><td>${fmt(v.filled_cells)}</td><td>${v.catchments.length}</td><td>${fmt(v.catchments.reduce((n,c)=>n+c.on_parcel_area_sqft,0))}</td><td>${fmt(v.known_ia_union_sqft)}</td></tr>`).join('');
 const economics=result.assessment?.research_drainage_scenarios?.scenarios||[];
 const moneyRows=economics.map(v=>`<tr><td>${esc(v.name)}</td><td>${esc(v.status)}</td><td>${money(v.gross_monthly_reduction)}</td><td>${money(v.gross_annual_reduction)}</td><td>${esc((v.reasons||[]).join('; '))}</td></tr>`).join('');
 host.innerHTML=`<div class="result-card"><h3>Villanova/Temple additional drainage evidence</h3><p>Runs alongside the current approach. Purple outlines show modeled GSI catchments. Neither method establishes treatment eligibility. Assumption ranges are not confidence intervals.</p><table><tr><th>Scenario</th><th>Grid</th><th>Filled cells</th><th>GSI catchments</th><th>On-parcel modeled ground (sq ft)</th><th>Known on-parcel IA (sq ft)</th></tr>${rows}</table><ul>${r.warnings.map(v=>'<li>'+esc(v)+'</li>').join('')}</ul><h4>Real-site validation still required</h4><ul>${r.validation.missing.map(v=>'<li>'+esc(v)+'</li>').join('')}</ul>${moneyRows?`<h4>Conditional bill-reduction alternatives</h4><p>Assumes all management prerequisites. Uses one reconciled ledger; do not add these alternatives to other savings.</p><table><tr><th>Scenario</th><th>Status</th><th>Monthly reduction</th><th>Annual reduction</th><th>Blockers</th></tr>${moneyRows}</table>`:''}<details><summary>Conditioning assumptions and feature coverage</summary><pre>${esc(JSON.stringify({source:r.source,parameters:p.parameters,features:p.feature_audit,omitted:r.omitted_features,comparison:r.comparison,raster_sha256:p.raster_sha256},null,2))}</pre></details></div>`;
}

function modeledScenarioRows(rows){return rows.map(s=>{const notes=[...(s.reasons||[]),s.financial_scope||'',s.scope||'',...(s.excluded_records||[]).map(r=>'Excluded '+r.record_id+': '+r.reasons.join('; '))].filter(Boolean);const row=`<tr><td>${esc(s.bound||s.name||'Alternative')}</td><td>${fmt(s.area_sqft)}</td><td>${esc(s.status)}</td><td>${money(s.gross_monthly_reduction)}</td><td>${money(s.gross_annual_reduction)}</td><td>${esc(notes.join('; '))}</td></tr>`;const net=s.net_with_area_correction;return row+(net?`<tr><td>Net with area correction</td><td>—</td><td>${esc(net.status)}</td><td>${money(net.gross_monthly_reduction)}</td><td>${money(net.gross_annual_reduction)}</td><td>${esc((net.reasons||[]).join('; '))}</td></tr>`:'');}).join('');}
function modeledRecordHtml(info){
 if(!info)return '';
 const composition=info.footprint_composition||info.runs?.[0]?.composition;
 const classes=composition?`<p>AI-estimated visible cover; ground beneath canopy remains unresolved.</p><table><tr><th>Class</th><th>Estimated area (sq ft)</th><th>Pixel-edge range</th></tr>${composition.classes.map(c=>`<tr><td>${esc(c.class.replaceAll('_',' '))}</td><td>${fmt(c.area_sqft)}</td><td>${fmt(c.edge_lower_sqft)}–${fmt(c.edge_upper_sqft)}</td></tr>`).join('')}</table>`:'';
 const runs=(info.runs||[]).map(r=>`<p><strong>${esc(r.name)}</strong> · catchment ${esc(r.catchment_match.status)} · ${esc(r.receiver_id||r.catchment_match.reason||'')}<br>${esc(r.area_basis||'No contributing area established')}</p><table><tr><th>Area assumption</th><th>Modeled IA (sq ft)</th><th>Status</th><th>Monthly reduction</th><th>Annual reduction</th><th>Blockers</th></tr>${modeledScenarioRows(r.scenarios||[])}</table>`).join('');
 return `<details class="modeled-record"><summary>AI and drainage estimates for this record</summary><p>${esc(info.reason||info.basis)}. Existing findings above remain unchanged. These alternatives require their listed assumptions.</p>${classes}${runs}<details><summary>Class areas, source dates, model hashes and assumed prerequisites</summary><pre>${esc(JSON.stringify(info,null,2))}</pre></details></details>`;
}
function modeledCombinedHtml(data){
 if(!data)return '';
 if(['invalidated','outdated','blocked'].includes(data.status))return `<div class="result-card warning"><h3>Model-derived savings unavailable</h3><p>${esc(data.reason||data.claim)}</p></div>`;
 const areaRows=(data.surface_scenario?.area_alternatives||[]).map(v=>`<tr><td>${esc(v.name.replaceAll('_',' '))}</td><td>${fmt(v.ga_sqft)}</td><td>${fmt(v.ia_sqft)}</td><td>${money(v.monthly_savings)}</td><td>${money(v.annual_savings)}</td><td>${esc((v.reasons||[]).join('; '))}</td></tr>`).join('');
 const gsiRows=(data.catchment_scenarios||[]).map(v=>({...v,bound:v.name+' / '+v.receiver_id+' / '+v.bound}));
 const permitRows=(data.permit_scenarios||[]).map(v=>({...v,bound:v.permit_id||v.record_id}));
 const rows=(data.combined||[]).map(v=>({...v,name:v.name+' / '+v.bound,bound:v.name+' / '+v.bound,area_sqft:v.record_areas_sqft?Object.values(v.record_areas_sqft).reduce((n,a)=>n+a,0):null}));
 return `<div class="result-card"><h3>AI/catchment-informed savings alternatives</h3><p>${esc(data.claim)} Bounds are sensitivity assumptions, not statistical confidence. Approval and actual savings remain unverified.</p><table><tr><th>Drainage / area assumption</th><th>Area</th><th>Status</th><th>Monthly reduction</th><th>Annual reduction</th><th>Blockers</th></tr>${modeledScenarioRows(rows)||'<tr><td colspan="6">No linked system area available; inspect the individual record findings.</td></tr>'}</table><h4>Area appeal assumptions</h4><p>Incomplete cover prevents a supported appeal. These explicit ground assumptions illustrate possible bills; negative reductions mean increases.</p><table><tr><th>Assumption</th><th>Gross area (sq ft)</th><th>Impervious area (sq ft)</th><th>Monthly reduction</th><th>Annual reduction</th><th>Blockers</th></tr>${areaRows}</table><h4>Mapped GSI management alternatives</h4><p>Only if existing treatment, parcel allocation, condition and approval meet the stated requirements. Individual and combined rows are alternatives.</p><table><tr><th>Drainage / receiver / area assumption</th><th>Area (sq ft)</th><th>Status</th><th>Monthly reduction</th><th>Annual reduction</th><th>Blockers</th></tr>${modeledScenarioRows(gsiRows)}</table><h4>Industrial permit what-if</h4><p>Coverage, site/operator match and compliance remain unverified. This is a conditional value only.</p><table><tr><th>Permit candidate</th><th>Area</th><th>Status</th><th>Monthly reduction</th><th>Annual reduction</th><th>Blockers</th></tr>${modeledScenarioRows(permitRows)}</table><h4>Canopy alternatives</h4><table><tr><th>Assumption</th><th>Modeled overlap (sq ft)</th><th>Status</th><th>Monthly reduction</th><th>Annual reduction</th><th>Blockers</th></tr>${modeledScenarioRows(data.canopy_scenarios||[])}</table><details><summary>Surface correction alternative, reconciled ledgers and image context</summary><pre>${esc(JSON.stringify({surface:data.surface_scenario,canopy:data.canopy_scenarios,combined:data.combined,catchments:data.catchment_scenarios,permits:data.permit_scenarios,image_context:data.image_context},null,2))}</pre></details></div>`;
}
function renderModelSummary(){
 const host=$('modeled-results');if(!host)return;const m=result?.modeled_integration;if(!m){host.innerHTML='';return;}
 if(['invalidated','outdated'].includes(m.status)){host.innerHTML=`<div class="result-card warning"><h3>AI-derived results withheld (older interpretation)</h3><p>${esc(m.reason)}</p><p>Historical files are preserved. Saved observations remain visible. Use Recompute from saved inputs to recalculate locally.</p></div>`;return;}
 host.innerHTML=`<div class="result-card"><h3>Connected AI surface and drainage estimates</h3><p>${esc(m.claim)}</p><p>AI source status: ${esc(m.ai.status)} · identified IA in modeled branch: ${fmt(m.measurement.ia_sqft)} sq ft · unresolved modeled ground: ${fmt(m.measurement.unknown_sqft)} sq ft · roof supplementation: ${fmt(m.roof_supplement_sqft)} sq ft.</p><p>Original measured IA: ${fmt(result.measurement.ia_sqft)} sq ft. ${esc(m.drainage_source)}. Dashed orange lines show AI-informed catchments.</p><p>Conflicting AI classes: ${fmt(m.ai.class_conflict_sqft)} sq ft · disagreements with recorded observations: ${fmt(m.ai.observation_disagreement_sqft)} sq ft.</p><ul>${m.ai.uncertainty.map(v=>'<li>'+esc(v)+'</li>').join('')}</ul><details><summary>Sources, excluded predictions and catchment composition</summary><pre>${esc(JSON.stringify({sources:m.ai.sources,excluded:m.ai.excluded,runs:m.runs},null,2))}</pre></details></div>`;
}
